package zw.ac.uz.dpdms.auth;
import com.auth0.jwt.*; import com.auth0.jwt.algorithms.Algorithm; import jakarta.validation.Valid; import java.time.*; import org.springframework.beans.factory.annotation.*; import org.springframework.http.*; import org.springframework.security.crypto.password.PasswordEncoder; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/auth") public class AuthController { private final UserRepository users; private final PasswordEncoder encoder; @Value("${DPDMS_JWT_SECRET:change-this-demo-secret-to-at-least-32-characters}") String secret; public AuthController(UserRepository u,PasswordEncoder e){users=u;encoder=e;}
 @PostMapping("/login") public ResponseEntity<?> login(@Valid @RequestBody LoginRequest req){AppUser u=users.findByUsername(req.username()).filter(x->encoder.matches(req.password(),x.passwordHash)).orElse(null); if(u==null)return ResponseEntity.status(HttpStatus.UNAUTHORIZED).body(java.util.Map.of("message","Invalid username or password")); String t=JWT.create().withSubject(u.username).withClaim("role",u.role).withClaim("hazard",u.hazard==null?"":u.hazard).withClaim("ward",u.ward==null?"":u.ward).withIssuedAt(Instant.now()).withExpiresAt(Instant.now().plus(Duration.ofHours(8))).sign(Algorithm.HMAC256(secret)); return ResponseEntity.ok(java.util.Map.of("token",t,"role",u.role));}}
